 async Task SaveCurrent(){
  await Flush(true);
  var native=backend as NativeBackend;if(native==null)throw new InvalidOperationException("La vista previa no guarda presets en el amplificador.");
  var destination=await native.ReadSaveContext();int b=destination.Bank,c=destination.Channel,n=destination.Index;
  if(MessageBox.Show(this,AppLanguage.Text("¿Quieres guardar los ajustes actuales en "+(b+1)+(c==1?"A":"B")+"? Antes se creará una copia local de estos ajustes."),AppLanguage.Text("Guardar preset"),MessageBoxButtons.OKCancel,MessageBoxIcon.Question)!=DialogResult.OK)return;
  await backend.Command("saveCurrentPresetToDeviceAtIndex",n);await RefreshDevice();message.Text="✓ Preset "+(b+1)+(c==1?"A":"B")+" guardado y confirmado por el amplificador.";message.ForeColor=UITheme.Success;
 }
 async Task PresetFile(bool load){
  if(load){using(var d=new OpenFileDialog{Filter=AppLanguage.Text("Preset Catalyst (*.catl6p)|*.catl6p")}){if(d.ShowDialog(this)!=DialogResult.OK)return;if(new FileInfo(d.FileName).Length>4000000)throw new InvalidDataException("Preset demasiado grande");revision++;pending.Clear();await backend.Command("loadPresetFromPath",d.FileName);await RefreshDevice();}}
  else using(var d=new SaveFileDialog{Filter=AppLanguage.Text("Preset Catalyst (*.catl6p)|*.catl6p"),FileName="Preset.catl6p"}){if(d.ShowDialog(this)!=DialogResult.OK)return;await backend.Command("savePresetToPath",d.FileName);message.Text="Preset exportado.";}
 }
 async Task Archive(bool restore){
  if(restore){using(var d=new OpenFileDialog{Filter=AppLanguage.Text("Copia Catalyst (*.catl6a)|*.catl6a")}){if(d.ShowDialog(this)!=DialogResult.OK)return;if(MessageBox.Show(this,AppLanguage.Text("Restaurar esta copia sustituye los presets y ajustes del ampli. ¿Continuar?"),AppLanguage.Text("Restaurar copia"),MessageBoxButtons.OKCancel,MessageBoxIcon.Warning)!=DialogResult.OK)return;string backup=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"CatalystCFEditor","backups",DateTime.UtcNow.ToString("yyyyMMdd-HHmmss-ffff"));Directory.CreateDirectory(backup);await backend.Command("saveDeviceArchiveToPath",Path.Combine(backup,"before.catl6a"));await backend.Command("restoreDeviceWithArchiveFromPath",d.FileName);await RefreshDevice();}}
  else using(var d=new SaveFileDialog{Filter=AppLanguage.Text("Copia Catalyst (*.catl6a)|*.catl6a"),FileName="Catalyst-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".catl6a"}){if(d.ShowDialog(this)!=DialogResult.OK)return;await backend.Command("saveDeviceArchiveToPath",d.FileName);message.Text="Copia completa exportada.";}
 }
