  Bind(new Binding("systemState",Catalog.Int("tunerCents","Cents",-50,50),false),display.SetCents);
  var tempoCard=StackCard(stack,"TEMPO",82);var tf=Flow(tempoCard);
  var tempo=new Binding("systemState",Catalog.Int("tempo","Tempo (ms)",250,3000));var bpm=new GlassNumber{Minimum=20,Maximum=240,Width=95,Margin=new Padding(6)};bool readingTempo=false;tf.Controls.Add(LabelText("BPM",true));tf.Controls.Add(bpm);Bind(tempo,v=>{int ms=Convert.ToInt32(v);if(ms<250||ms>3000)return;readingTempo=true;bpm.Value=EngineUnits.TempoBpm(ms);readingTempo=false;});bpm.ValueChanged+=delegate{if(!readingTempo)Queue(tempo,EngineUnits.TempoMs((int)bpm.Value));};Track(bpm,tempo);tf.Controls.Add(Button("TAP",()=>{var now=DateTime.UtcNow;if(lastTap!=DateTime.MinValue){double ms=(now-lastTap).TotalMilliseconds;if(ms>=250&&ms<=3000)Queue(tempo,(int)Math.Round(ms));}lastTap=now;},105));
