 void AddChoice(Control parent,Binding b){var f=new FlowLayoutPanel{AutoSize=true,BackColor=Color.Transparent,WrapContents=false,Margin=new Padding(2)};f.Controls.Add(LabelText(b.Param.name,true));var c=Combo();c.Width=195;c.Items.AddRange(b.Param.choices);bool setting=false;Bind(b,v=>{setting=true;int n=Convert.ToInt32(v)-(int)b.Param.minimum;c.SelectedIndex=n>=0&&n<c.Items.Count?n:-1;setting=false;});c.SelectedIndexChanged+=delegate{if(!setting&&c.SelectedIndex>=0)Queue(b,c.SelectedIndex+(int)b.Param.minimum);};f.Controls.Add(c);parent.Controls.Add(f);Track(c,b);}
 void Number(Control parent,Binding b){var f=new FlowLayoutPanel{AutoSize=true,BackColor=Color.Transparent,WrapContents=false};f.Controls.Add(LabelText(b.Param.name,true));var n=new GlassNumber{Minimum=(decimal)b.Param.minimum,Maximum=(decimal)b.Param.maximum,Width=90,Margin=new Padding(6)};bool setting=false;Bind(b,v=>{decimal value=Convert.ToDecimal(v);if(value<n.Minimum||value>n.Maximum)return;setting=true;n.Value=value;setting=false;});n.ValueChanged+=delegate{if(!setting)Queue(b,(int)n.Value);};f.Controls.Add(n);parent.Controls.Add(f);deviceControls.Add(n);}
