 void RefreshAdvanced(){if(advanced==null||advanced.IsCurrentCellInEditMode)return;advanced.Rows.Clear();advancedBindings.Clear();foreach(var b in bindings.Where(b=>b.Editable&&(b.Param.kind=="int"||b.Param.kind=="bool")).GroupBy(b=>b.Key).Select(x=>x.First()).OrderBy(b=>b.Group).ThenBy(b=>b.Param.name)){object value;if(!values.TryGetValue(b.Key,out value))continue;int raw=value is bool?((bool)value?1:0):Convert.ToInt32(value);int i=advanced.Rows.Add(b.Group,b.Param.name,raw,b.Param.minimum+" … "+b.Param.maximum,b.Param.Display(raw));advancedBindings[i]=b;}}
 void OnAdvancedEdit(object sender,DataGridViewCellValidatingEventArgs e){if(e.ColumnIndex!=2||refreshing)return;Binding b;if(!advancedBindings.TryGetValue(e.RowIndex,out b))return;int value;if(!int.TryParse(Convert.ToString(e.FormattedValue),out value)){e.Cancel=true;return;}try{b.Param.Validate(value);Queue(b,b.Param.kind=="bool"?(object)(value!=0):(object)value);advanced.Rows[e.RowIndex].Cells[4].Value=b.Param.Display(value);}catch(Exception error){e.Cancel=true;Error(error);}}
}
